import{_ as s,a0 as p,w as l,s as n,ao as u,I as r,a1 as a,A as i,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"如何使用 VLC 媒體播放器旋轉視頻 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 VLC 媒體播放器旋轉視頻 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 VLC 媒體播放器旋轉視頻 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 VLC 媒體播放器旋轉視頻 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230819 How to Rotate a Video With VLC Media Player","title":"如何使用 VLC 媒體播放器旋轉視頻","tag":"202308","desc":""},"relativePath":"202308/20230819 How to Rotate a Video With VLC Media Player.md","filePath":"[post].md"}'),d={name:"202308/20230819 How to Rotate a Video With VLC Media Player.md"};function m(b,t,f,g,C,c){const o=p("Link");return l(),n("div",null,[t[16]||(t[16]=u('<h1 id="如何使用-vlc-媒體播放器旋轉視頻" tabindex="-1">如何使用 VLC 媒體播放器旋轉視頻 <a class="header-anchor" href="#如何使用-vlc-媒體播放器旋轉視頻" aria-label="Permalink to “如何使用 VLC 媒體播放器旋轉視頻”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/26/110201gf37d3djvis66seu.jpg" alt=""></p><blockquote><p>這個多功能的 VLC 媒體播放器還可以旋轉視頻方向。在桌面上觀看智能手機錄製的視頻相當方便。</p></blockquote><p>有時，你會遇到以顯示方向錯誤的視頻。使用智能手機攝像頭拍攝的視頻很可能會以這種方式出現。</p><p>如果你可以將其旋轉到方便的方向，那麼效果會更好。</p><p>功能豐富的 VLC 媒體播放器提供了一種旋轉視頻的方法。你可以：</p><ul><li>暫時旋轉視頻（下次播放時需要再次旋轉）</li><li>永久旋轉視頻（視頻將始終以新方向播放）</li></ul><p>讓我們看看如何實現這兩者之一。</p><h3 id="在-vlc-中暫時旋轉視頻" tabindex="-1">在 VLC 中暫時旋轉視頻 <a class="header-anchor" href="#在-vlc-中暫時旋轉視頻" aria-label="Permalink to “在 VLC 中暫時旋轉視頻”">​</a></h3><p>讓我們看看如何在 VLC 中臨時旋轉視頻。也就是説，完成該過程後，它不會反映在實際文件上。這對於查看文件或測試文件很有用。</p><h4 id="使用預設值旋轉視頻" tabindex="-1">使用預設值旋轉視頻 <a class="header-anchor" href="#使用預設值旋轉視頻" aria-label="Permalink to “使用預設值旋轉視頻”">​</a></h4><p>在此方法中，你可以將視頻旋轉 90 度、180 度和 270 度。這是你大多數時候所需要的。</p><p>打開 VLC 並選擇要旋轉的視頻。</p><p><img src="https://itsfoss.com/content/images/2023/08/open-a-file-in-vlc.png" alt="Open File in VLC"></p><p>單擊主菜單上的 “<ruby>工具<rt>Tools</rt></ruby>”，然後轉到 “<ruby>效果和濾鏡<rt>Effects and Filters</rt></ruby>”。你也可以按快捷鍵 <code>CTRL + E</code>。</p><p><img src="https://itsfoss.com/content/images/2023/08/effects-and-filters-in-main-menu.png" alt="Tools &gt; Effects and Filters"></p><p>在 “效果和濾鏡” 頁面上，選擇 “<ruby>視頻效果<rt>Video Effects</rt></ruby>” 選項卡，然後進入 “<ruby>幾何<rt>Geometry</rt></ruby>”。現在，選中 “<ruby>變換<rt>Transform</rt></ruby>” 複選框。</p><p><img src="https://itsfoss.com/content/images/2023/08/rotate-video-in-transform.png" alt="Set the Rotation"></p><p>這將激活一個下拉菜單。從那裏，選擇你需要的適當旋轉，如 90 度、180 度、水平翻轉等。你可以在 VLC 窗口中查看變化。</p><p>對更改感到滿意後，按 “<ruby>保存<rt>Save</rt></ruby>” 按鈕以所選方向保存配置。</p><h4 id="使用自定義值旋轉視頻" tabindex="-1">使用自定義值旋轉視頻 <a class="header-anchor" href="#使用自定義值旋轉視頻" aria-label="Permalink to “使用自定義值旋轉視頻”">​</a></h4><p>需要將視頻旋轉到可用預設以外的方向？ VLC 也有一個選項。</p><p>首先，像上一步一樣，打開媒體，然後轉到 “工具 &gt; 效果和濾鏡 &gt; 視頻效果 &gt; 幾何”。</p><p>現在，單擊 “<ruby>旋轉<rt>Rotate</rt></ruby>” 複選框，你可以看到交互式圓形滑塊現已激活。</p><blockquote><p>🚧 對於不規則的旋轉值（例如 230 度等），某些部分都會從視頻中刪除。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/08/rotate.png" alt="Irregular rotation"></p><p>移動滑塊以獲得正確的旋轉。你可以在 VLC 窗口中看到視頻出現的變化。確定更改後，請按 “保存” 按鈕保存該配置。</p><blockquote><p>🚧 請記住，此配置在此階段不會永久應用於視頻。但是，如果你按 “保存”，方向也會暫時應用於 VLC 中播放的其他視頻。</p></blockquote><h3 id="永久旋轉視頻" tabindex="-1">永久旋轉視頻 <a class="header-anchor" href="#永久旋轉視頻" aria-label="Permalink to “永久旋轉視頻”">​</a></h3><p>你知道了如何臨時旋轉文件。永久保存視頻文件更改也需要該步驟。</p><h4 id="第-1-步-轉換視頻" tabindex="-1">第 1 步：轉換視頻 <a class="header-anchor" href="#第-1-步-轉換視頻" aria-label="Permalink to “第 1 步：轉換視頻”">​</a></h4><p>這是前一部分。打開視頻文件，然後進行所需的旋轉。確認特定視頻所需的旋轉後，按照上一步中的説明保存該配置。</p><h4 id="第-2-步-保存視頻" tabindex="-1">第 2 步：保存視頻 <a class="header-anchor" href="#第-2-步-保存視頻" aria-label="Permalink to “第 2 步：保存視頻”">​</a></h4><p>現在，打開 VLC 並單擊 “<ruby>媒體<rt>Media</rt></ruby> &gt; <ruby>轉換/保存<rt>Convert/Save</rt></ruby>”。這可以在沒有打開任何視頻文件的情況下進行，因為無論如何我們都不會處理當前打開的視頻。</p><p><img src="https://itsfoss.com/content/images/2023/08/click-on-convert-and-save.png" alt="Click on Convert/Save"></p><p>在下一個對話框中，使用 “<ruby>添加<rt>Add</rt></ruby>” 按鈕選擇要旋轉的文件（在上一步中測試以確認所需旋轉的文件）。然後按 “<ruby>轉換並保存<rt>Convert and Save</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/08/Add-files-to-convert.png" alt="Add Files to convert"></p><p>接下來，選擇所需的視頻輸出，然後單擊相鄰的設置按鈕，如下所示。</p><p><img src="https://itsfoss.com/content/images/2023/08/click-on-config-button.png" alt="Click on Configuration button"></p><p>出現了配置文件設置窗口。在其上，進入 “<ruby>視頻編解碼器<rt>Video Codec</rt></ruby>”，然後轉到 “<ruby>過濾器<rt>Filters</rt></ruby>” 選項卡。在這裏，你必須根據需要應用過濾器。一個是 “<ruby>旋轉視頻過濾器<rt>Rotate Video Filter</rt></ruby>”，另一個是 “<ruby>視頻轉換過濾器<rt>Video transformation Filter</rt></ruby>”。</p><p>如果你已使用 “變換” 按鈕對視頻應用固定變換，請選擇 “<ruby>視頻變換過濾器<rt>Video transformation Filter</rt></ruby>”。另一方面，如果你對視頻進行了一些不規則的旋轉，請選擇 “旋轉視頻過濾器”。</p><p><img src="https://itsfoss.com/content/images/2023/08/apply-filters.png" alt="Apply the Filters"></p><p>檢查後，按 “保存”按鈕。</p><p>現在，選擇輸出文件位置，我們要在其中保存轉換後的文件。</p><p><img src="https://itsfoss.com/content/images/2023/08/give-an-output-file-name.png" alt="Select Output file location"></p><p>應給出一個新的文件名，這可以通過進入你選擇的目錄並只需在頂部欄上輸入你選擇的名稱來完成。</p><blockquote><p>💡 建議提供一個新的唯一名稱，以避免文件覆蓋和數據丟失。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/08/select-filename.png" alt="Give file name"></p><p>按 “<ruby>開始<rt>Start</rt></ruby>” 開始轉換。</p><p>轉換將需要一些時間，具體取決於你的視頻。完成後，你將獲得旋轉的視頻，可以在任何視頻播放器上查看。</p><blockquote><p>🚧 轉換視頻後（無論是永久的還是臨時的），最好在 “工具 &gt; 效果和濾鏡 &gt; 視頻效果 &gt; 幾何” 中關閉應用的旋轉。否則，以後使用 VLC 播放的視頻將出現旋轉。</p></blockquote><p>我希望你喜歡這個 VLC 技巧。歡迎你提出建議和反饋。</p><p>同時，你還可以學習這個很酷的 VLC 自動下載字幕的技巧。</p>',53)),r("blockquote",null,[r("p",null,[r("strong",null,[a(o,{href:"https://itsfoss.com/download-subtitles-automatically-vlc-media-player-ubuntu/"},{default:i(()=>[...t[0]||(t[0]=[e("在 VLC 中自動下載字幕",-1)])]),_:1})])])]),t[17]||(t[17]=r("p",null,[r("em",null,"（題圖：MJ/b604f181-660a-4f05-bdd2-49b5b6da0bae）")],-1)),t[18]||(t[18]=r("hr",null,null,-1)),r("p",null,[t[2]||(t[2]=e("via: ",-1)),a(o,{href:"https://itsfoss.com/rotate-video-vlc/"},{default:i(()=>[...t[1]||(t[1]=[e("https://itsfoss.com/rotate-video-vlc/",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=e("作者：",-1)),a(o,{href:"https://itsfoss.com/author/sreenath/"},{default:i(()=>[...t[3]||(t[3]=[e("Sreenath",-1)])]),_:1}),t[8]||(t[8]=e(" 選題：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[4]||(t[4]=[e("lujun9972",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const L=s(d,[["render",m]]);export{V as __pageData,L as default};
